// zerrors_darwin_arm64 — Darwin's constant table.
//
// Go: `syscall/zerrors_darwin_arm64.go`, generated by `mkerrors.sh` from
// the SDK headers. This file is the same thing by the same method:
// every numeric value below was read out of
// `$(xcrun --show-sdk-path)/usr/include` by compiling and running a
// program that prints them, not written from memory.
//
// **Why that matters more here than anywhere else in the port.** These
// constants are the part of the Darwin surface that rustc cannot check.
// A missing function is a compile error; a Linux number left in a
// Darwin file compiles clean and is wrong at runtime, silently. And
// they really do differ — not at the margins:
//
//   SIGURG    Linux 23  Darwin 16     SIGUSR1   Linux 10  Darwin 30
//   SIGCHLD   Linux 17  Darwin 20     SIGSTOP   Linux 19  Darwin 17
//   SIGCONT   Linux 18  Darwin 19     SIGUSR2   Linux 12  Darwin 31
//   EAGAIN    Linux 11  Darwin 35     ENOSYS    Linux 38  Darwin 78
//   ENOTEMPTY Linux 39  Darwin 66     EOPNOTSUPP Linux 95 Darwin 102
//   SA_ONSTACK 0x08000000 → 1         SA_SIGINFO 4 → 64
//   MAP_ANONYMOUS 0x20 → MAP_ANON 0x1000
//   O_CLOEXEC 0o2000000 → 0x1000000   AT_FDCWD  -100 → -2
//   SOL_SOCKET 1 → 0xffff             SO_ERROR 4 → 0x1007
//
// SIGURG is the one that would have been most expensive to find by
// hand: it is goish's async-preemption signal, so a Linux 23 here would
// have sent SIGUSR1 to every M.
//
// ─── Constants with no Darwin analogue ────────────────────────────────
//
// futex, clone, arch_prctl, epoll, eventfd, inotify, fanotify and
// `SA_RESTORER` are Linux kernel interfaces, not merely Linux spellings.
// Their names still have to resolve, because the code that uses them
// (`runtime/netpoll`, `runtime/note`, `os/inotify`) compiles on this
// target even though none of it runs yet.
//
// Every one of them is defined as `POISON` rather than as a plausible
// number. A zero or a copied-from-Linux value would flow through bit
// arithmetic and produce a wrong result somewhere far away; an all-ones
// value fails whatever it reaches, and `grep POISON` enumerates the
// entire set. The functions that would consume them are
// `unimplemented!()` in `syscall_darwin.rs`, so nothing reaches them
// today — the poison is the backstop for when M7/M9 start moving.

// ─── signals ───────────────────────────────────────────────────────────
//
// Go: `syscall/zerrors_darwin_arm64.go`; SDK `sys/signal.h`.
pub const SIGHUP: i32 = 1;
pub const SIGINT: i32 = 2;
pub const SIGQUIT: i32 = 3;
pub const SIGILL: i32 = 4;
pub const SIGTRAP: i32 = 5;
pub const SIGABRT: i32 = 6;
pub const SIGFPE: i32 = 8;
pub const SIGKILL: i32 = 9;
/// **10 on Darwin, 7 on Linux.** Darwin raises it, not SIGSEGV, for
/// an access to a `PROT_NONE` page — a goroutine stack's guard.
pub const SIGBUS: i32 = 10;
pub const SIGSEGV: i32 = 11;
pub const SIGPIPE: i32 = 13;
pub const SIGALRM: i32 = 14;
pub const SIGTERM: i32 = 15;
/// **16 on Darwin, 23 on Linux.** goish's async-preemption signal
/// (M8) — Go picks SIGURG for the same reason on both
/// (`runtime/signal_unix.go`, `preemptM` → `signalM(mp, sigPreempt)`).
pub const SIGURG: i32 = 16;
pub const SIGSTOP: i32 = 17;
pub const SIGTSTP: i32 = 18;
pub const SIGCONT: i32 = 19;
pub const SIGCHLD: i32 = 20;
pub const SIGTTIN: i32 = 21;
pub const SIGTTOU: i32 = 22;
pub const SIGXCPU: i32 = 24;
pub const SIGXFSZ: i32 = 25;
pub const SIGWINCH: i32 = 28;
pub const SIGUSR1: i32 = 30;
pub const SIGUSR2: i32 = 31;

// ─── sigaction flags ───────────────────────────────────────────────────
pub const SA_ONSTACK: u64 = 0x0001;
pub const SA_RESTART: u64 = 0x0002;
pub const SA_SIGINFO: u64 = 0x0040;

/// **No Darwin analogue**, and so 0: `SA_RESTORER` is the amd64-Linux
/// mechanism for supplying a userspace `rt_sigreturn` trampoline; BSD
/// `sigaction` has no `sa_restorer` field at all and libSystem's own
/// trampoline returns from the handler. Every `Sigaction` literal in
/// `runtime/` ORs it in, so it must be a no-op bit rather than poison.
/// See `sigreturn_restorer` in `syscall_darwin.rs`.
pub const SA_RESTORER: u64 = 0;

// ─── clock ids ─────────────────────────────────────────────────────────
//
// `CLOCK_MONOTONIC` is 6 here and 1 on Linux, and the difference is
// not only the number: Darwin's counts time asleep, Linux's does not.
// `CLOCK_UPTIME_RAW` (8) is the one that does not — it is
// `mach_absolute_time` *with* the timebase conversion applied, i.e. Go's
// darwin `nanotime` — and `runtime::sysmon::NANOTIME_CLOCK` selects it.
pub const CLOCK_REALTIME: i32 = 0;
pub const CLOCK_MONOTONIC: i32 = 6;
pub const CLOCK_MONOTONIC_RAW: i32 = 4;
pub const CLOCK_UPTIME_RAW: i32 = 8;

/// `utimensat` "leave this timestamp alone". Darwin spells it `-2`;
/// Linux uses the bit pattern `0x3ffffffe`.
pub const UTIME_OMIT: i64 = -2;

// ─── standard fds ──────────────────────────────────────────────────────
pub const STDIN: i32 = 0;
pub const STDOUT: i32 = 1;
pub const STDERR: i32 = 2;

// ─── mmap ──────────────────────────────────────────────────────────────
pub const PROT_NONE: i32 = 0;
pub const PROT_READ: i32 = 1;
pub const PROT_WRITE: i32 = 2;
pub const PROT_EXEC: i32 = 4;

pub const MAP_PRIVATE: i32 = 0x02;
pub const MAP_FIXED: i32 = 0x10;
/// Darwin spells it `MAP_ANON` and numbers it `0x1000`; Linux's
/// `MAP_ANONYMOUS` is `0x20`. The goish name follows Linux because
/// every caller already uses it.
pub const MAP_ANONYMOUS: i32 = 0x1000;
/// Present in the SDK (`0x40`) but documented as a no-op on Darwin —
/// there is no commit-charge accounting to opt out of. Kept so the
/// goroutine-stack reservation path compiles; M2 decides whether to
/// pass it at all.
pub const MAP_NORESERVE: i32 = 0x40;

/// `madvise(2)` advice. **`MADV_DONTNEED` exists here and does not do
/// what it does on Linux** — it does not free the pages and does not
/// zero them. Go's Darwin release path is the `MADV_FREE_REUSABLE` /
/// `MADV_FREE_REUSE` pair (`runtime/mem_darwin.go:23-34`). M2 owns the
/// choice; both are spelled out here so it is made explicitly.
pub const MADV_DONTNEED: i32 = 4;
pub const MADV_FREE: i32 = 5;
pub const MADV_FREE_REUSABLE: i32 = 7;
pub const MADV_FREE_REUSE: i32 = 8;

/// Sentinel returned by `mmap(2)` on failure (`(void *) -1`).
pub const MAP_FAILED: *mut u8 = !0usize as *mut u8;

