pub const O_RDONLY: i32 = 0x0;
pub const O_WRONLY: i32 = 0x1;
pub const O_RDWR: i32 = 0x2;
pub const O_NONBLOCK: i32 = 0x4;
pub const O_APPEND: i32 = 0x8;
pub const O_CREAT: i32 = 0x200;
pub const O_TRUNC: i32 = 0x400;
pub const O_DIRECTORY: i32 = 0x100000;
pub const O_CLOEXEC: i32 = 0x1000000;

/// **No Darwin analogue.** Linux's `O_PATH` opens a descriptor that
/// refers to a path without granting read or write. Darwin has no
/// equivalent flag.
pub const O_PATH: i32 = POISON_I32;

pub const F_GETFD: i32 = 1;
pub const F_SETFD: i32 = 2;
pub const F_GETFL: i32 = 3;
pub const F_SETFL: i32 = 4;
pub const F_NOCACHE: i32 = 48;
/// Darwin's real "flush to platter" — plain `fsync(2)` on macOS only
/// hands the data to the drive. Go: `internal/poll/fd_fsync_darwin.go`.
pub const F_FULLFSYNC: i32 = 51;
pub const FD_CLOEXEC: i32 = 1;

/// **-2 on Darwin, -100 on Linux.**
pub const AT_FDCWD: i32 = -2;
pub const AT_REMOVEDIR: i32 = 0x80;
pub const AT_SYMLINK_NOFOLLOW: i32 = 0x20;

// ─── stat / seek / flock ───────────────────────────────────────────────
//
// The `S_IF*` values are POSIX and identical to Linux's. **The type is
// not:** Darwin's `mode_t` is 16-bit, so `struct stat`'s `st_mode` is a
// `u16` sitting at offset 4 with `st_nlink` immediately after it at
// offset 6 — there is no room to widen it. Go makes the same split
// (`syscall.Stat_t.Mode` is `uint16` on darwin, `uint32` on linux).
//
// Typing the constants to match keeps every caller portable with no
// cast: `st.st_mode & S_IFMT` is `u16 & u16` here and `u32 & u32` on
// Linux, and `(st.st_mode & 0o777) as u32` works unchanged on both.
pub const S_IFMT: u16 = 0o170000;
pub const S_IFDIR: u16 = 0o040000;
pub const S_IFREG: u16 = 0o100000;
pub const S_IFLNK: u16 = 0o120000;

pub const SEEK_SET: i32 = 0;
pub const SEEK_CUR: i32 = 1;
pub const SEEK_END: i32 = 2;

pub const LOCK_SH: i32 = 1;
pub const LOCK_EX: i32 = 2;
pub const LOCK_NB: i32 = 4;
pub const LOCK_UN: i32 = 8;

// ─── dirent types ──────────────────────────────────────────────────────
//
// Also identical — 4.4BSD's `d_type` values, which Linux adopted.
pub const DT_UNKNOWN: u8 = 0;
pub const DT_FIFO: u8 = 1;
pub const DT_CHR: u8 = 2;
pub const DT_DIR: u8 = 4;
pub const DT_BLK: u8 = 6;
pub const DT_REG: u8 = 8;
pub const DT_LNK: u8 = 10;
pub const DT_SOCK: u8 = 12;

// ─── sockets ───────────────────────────────────────────────────────────
pub const AF_UNIX: i32 = 1;
pub const AF_INET: i32 = 2;
/// 30 on Darwin, 10 on Linux.
pub const AF_INET6: i32 = 30;

pub const SOCK_STREAM: i32 = 1;
pub const SOCK_DGRAM: i32 = 2;

/// **No Darwin analogue in the kernel.** Linux folds `SOCK_CLOEXEC` /
/// `SOCK_NONBLOCK` into the `type` argument of `socket(2)` and
/// `accept4(2)`; BSD has neither, and Go sets both with `fcntl` after
/// the fact (`internal/poll/sys_cloexec.go`). goish's `Socket`,
/// `Accept4` and `Socketpair` on this target strip these bits from
/// `type` and do the same, so callers spell them as on Linux. High
/// bits, clear of every real `SOCK_*` type.
pub const SOCK_CLOEXEC: i32 = 0x1000_0000;
pub const SOCK_NONBLOCK: i32 = 0x2000_0000;

pub const IPPROTO_TCP: i32 = 6;
pub const IPPROTO_UDP: i32 = 17;
pub const IPPROTO_IPV6: i32 = 41;

/// **0xffff on Darwin, 1 on Linux.**
pub const SOL_SOCKET: i32 = 0xffff;
pub const SO_REUSEADDR: i32 = 0x0004;
pub const SO_KEEPALIVE: i32 = 0x0008;
pub const SO_LINGER: i32 = 0x0080;
pub const SO_REUSEPORT: i32 = 0x0200;
pub const SO_SNDTIMEO: i32 = 0x1005;
pub const SO_RCVTIMEO: i32 = 0x1006;
pub const SO_ERROR: i32 = 0x1007;
pub const SO_TYPE: i32 = 0x1008;
/// Per-socket SIGPIPE suppression. Darwin-only, and the reason the
/// process-wide `SIG_IGN` in `__goish_rt0` has a cleaner answer here
/// than on Linux. Go uses it in `net/sockopt_bsd.go`.
pub const SO_NOSIGPIPE: i32 = 0x1022;

/// 27 on Darwin, 26 on Linux.
pub const IPV6_V6ONLY: i32 = 27;

pub const TCP_NODELAY: i32 = 1;
/// Darwin's `TCP_KEEPALIVE` (0x10) is the analogue of Linux's
/// `TCP_KEEPIDLE` (4) — same role, different name and number. Go maps
/// them in `net/tcpsockopt_darwin.go`.
pub const TCP_KEEPIDLE: i32 = 0x10;
pub const TCP_KEEPINTVL: i32 = 0x101;
pub const TCP_KEEPCNT: i32 = 0x102;

pub const SHUT_RD: i32 = 0;
pub const SHUT_WR: i32 = 1;
pub const SHUT_RDWR: i32 = 2;

pub const INADDR_ANY: u32 = 0;

pub const MSG_PEEK: i32 = 0x2;
/// 0x80 on Darwin, 0x40 on Linux.
pub const MSG_DONTWAIT: i32 = 0x80;

// ─── termios ───────────────────────────────────────────────────────────
//
// The `ioctl` request numbers are BSD `_IOR`/`_IOW` encodings and share
// nothing with Linux's small integers. The goish names keep the Linux
// spelling; the values are Darwin's `TIOCGETA` / `TIOCSETA`.
pub const TCGETS: usize = 0x40487413;
pub const TCSETS: usize = 0x80487414;
pub const TIOCGWINSZ: usize = 0x40087468;
pub const TIOCSWINSZ: usize = 0x80087467;
/// Darwin's `TIOCPTYGNAME` returns the *name* of the pty, where Linux's
/// `TIOCGPTN` returns its number — same purpose, incompatible result,
/// so the pty code needs more than a renumber. Not M1's problem.
pub const TIOCGPTN: usize = 0x40807453;
/// Darwin's `TIOCPTYUNLK`. Linux's `TIOCSPTLCK` takes a pointer to an
/// int; this one takes no argument.
pub const TIOCSPTLCK: usize = 0x20007452;

// c_iflag / c_oflag / c_cflag / c_lflag bits.
//
// **Typed `u64`, not `u32`.** Darwin's `tcflag_t` is `unsigned long`,
// so `struct termios` is four 8-byte flag words where Linux has four
// 4-byte ones (measured: `c_ispeed` sits at offset 56 here, 20 there).
// The bit values below are POSIX for the low `c_iflag` bits and diverge
// from Linux everywhere else.
pub const IGNBRK: u64 = 0x1;
pub const BRKINT: u64 = 0x2;
pub const PARMRK: u64 = 0x8;
pub const ISTRIP: u64 = 0x20;
pub const INLCR: u64 = 0x40;
pub const IGNCR: u64 = 0x80;
pub const ICRNL: u64 = 0x100;
/// 0x200 on Darwin, 0x400 on Linux — the first `c_iflag` bit to diverge.
pub const IXON: u64 = 0x200;

pub const OPOST: u64 = 0x1;

// c_cflag — 0x300 here against Linux's 0x30.
pub const CSIZE: u64 = 0x300;
pub const CS8: u64 = 0x300;
pub const PARENB: u64 = 0x1000;

// c_lflag — every one of these differs from Linux.
pub const ECHO: u64 = 0x8;
pub const ECHONL: u64 = 0x10;
pub const ISIG: u64 = 0x80;
pub const ICANON: u64 = 0x100;
pub const IEXTEN: u64 = 0x400;

// c_cc indices — 16/17 here, 6/5 on Linux, and swapped in order.
pub const VMIN: usize = 16;
pub const VTIME: usize = 17;

// ─── poll ──────────────────────────────────────────────────────────────
pub const POLLIN: i16 = 0x1;
pub const POLLERR: i16 = 0x8;
pub const POLLHUP: i16 = 0x10;
pub const POLLNVAL: i16 = 0x20;

// ─── Linux-only interfaces ─────────────────────────────────────────────
//
// See the header. Names resolve; values are poison; the functions that
// consume them are `unimplemented!()`.

/// Poison for a Linux-only constant with no Darwin analogue. All-ones
/// so it fails whatever it reaches instead of looking plausible.
const POISON_I32: i32 = -1;
const POISON_U32: u32 = !0;
const POISON_U64: u64 = !0;

// futex(2) — no syscall of that name on Darwin, but `syscall::Futex`
// implements these two operations over `__ulock_wait2`/`__ulock_wake`
// (M7). The values are Linux's so the two surfaces spell them alike;
// only `Futex` on this target interprets them.
pub const FUTEX_PRIVATE_FLAG: i32 = 128;
pub const FUTEX_WAIT_PRIVATE: i32 = 0 | FUTEX_PRIVATE_FLAG;
pub const FUTEX_WAKE_PRIVATE: i32 = 1 | FUTEX_PRIVATE_FLAG;

// arch_prctl(2) — x86-Linux only; unreachable on any arm64 target.
pub const ARCH_SET_FS: i32 = POISON_I32;
pub const ARCH_GET_GS: i32 = POISON_I32;
pub const ARCH_SET_GS: i32 = POISON_I32;
pub const ARCH_GET_FS: i32 = POISON_I32;

// clone(2) — Darwin creates threads with `pthread_create`
// (Go: `runtime/os_darwin.go:233-258`). M4.
pub const CLONE_VM: u64 = POISON_U64;
pub const CLONE_FS: u64 = POISON_U64;
pub const CLONE_FILES: u64 = POISON_U64;
pub const CLONE_SIGHAND: u64 = POISON_U64;
pub const CLONE_THREAD: u64 = POISON_U64;
pub const CLONE_SYSVSEM: u64 = POISON_U64;
pub const CLONE_SETTLS: u64 = POISON_U64;
pub const CLONE_THREAD_FLAGS: u64 = POISON_U64;

// epoll — no such kernel interface on Darwin, but `EpollCreate1`,
// `EpollCtl` and `EpollPwait` translate these onto kqueue (see the note
// above `epoll_create1` in `syscall_darwin.rs`). The values are
// Linux's so both surfaces spell them alike.
pub const EPOLL_CTL_ADD: i32 = 1;
pub const EPOLL_CTL_DEL: i32 = 2;
pub const EPOLL_CTL_MOD: i32 = 3;
pub const EPOLLIN: u32 = 0x001;
pub const EPOLLOUT: u32 = 0x004;
pub const EPOLLERR: u32 = 0x008;
pub const EPOLLHUP: u32 = 0x010;
pub const EPOLLRDHUP: u32 = 0x2000;
pub const EPOLLET: u32 = 1 << 31;
pub const EPOLLONESHOT: u32 = 1 << 30;

// eventfd(2) — no analogue; the kqueue wake replaces its role.
pub const EFD_CLOEXEC: i32 = POISON_I32;
pub const EFD_NONBLOCK: i32 = POISON_I32;

// getrandom(2) flags — Darwin's entropy source is `arc4random_buf`,
// which is infallible and takes no flags (Go: `runtime/os_darwin.go`,
