pub const IN_CLOEXEC: i32 = POISON_I32;
pub const IN_NONBLOCK: i32 = POISON_I32;
pub const IN_MODIFY: u32 = POISON_U32;
pub const IN_MOVED_FROM: u32 = POISON_U32;
